previewCss:
.darma-loader-darma-b14-cursor-click { --accent: var(--loader-color, #1e293b); --accent-2: var(--loader-secondary-color, #0ea5e9); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; }
.darma-loader-darma-b14-cursor-click::after { content: ''; position: absolute; z-index: 2; top: 22%; left: 28%; width: 36%; height: 48%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); clip-path: polygon(0 0, 0 84%, 24% 62%, 44% 100%, 62% 90%, 40% 54%, 76% 50%); animation: darma-loader-darma-b14-cursor-click-click-press calc(var(--loader-speed, 1s) * 1.8) ease-out infinite; }
.darma-loader-darma-b14-cursor-click span { position: absolute; top: 58%; left: 38%; width: 22%; height: 22%; border-radius: 50%; border: calc(var(--loader-size, 84px) * .03) solid var(--accent-2); animation: darma-loader-darma-b14-cursor-click-click-ring calc(var(--loader-speed, 1s) * 1.8) ease-out infinite; }
.darma-loader-darma-b14-cursor-click span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .18); }
@keyframes darma-loader-darma-b14-cursor-click-click-press { 0%, 48% { transform: translate(0, 0); } 58% { transform: translate(6%, 8%) scale(.93); } 72%, 100% { transform: translate(0, 0); } }
@keyframes darma-loader-darma-b14-cursor-click-click-ring { 0%, 50% { opacity: 0; transform: scale(.3); } 60% { opacity: 1; } 100% { opacity: 0; transform: scale(2.1); } }

